/**
 * Finish frame processing - write physics state back to shared buffers.
 *
 * @param {Object} body - Physics body object
 * @param {Object} sDynamic - Shared buffer view for this body
 * @param {Object|null} sDynamicTemp - Temp buffer view (for dynamic bodies)
 * @param {string} type - Body type: 'dynamic', 'kinematic', or 'companion'
 */
export function finishFrame(body: any, sDynamic: any, sDynamicTemp: any | null, type: string): void;
export function writeCurrent(sDynamic: any, body: any): void;
